/* Overlays (*_REL.BIN).
 *
 * On the PS1 the game reads one overlay at a time from disc into a shared
 * memory area and jumps into it. Natively all overlays are compiled into the
 * executable, so a "load" only has to put the overlay back into the state a
 * fresh load gave it: its .data restored to the initial values and its .bss
 * cleared. The linker script generated by CMakeLists.txt groups each overlay's
 * writable data into one section with start/end symbols; dw1_overlay_init()
 * snapshots them before the game runs and dw1_overlay_reset() copies the
 * snapshot back.
 *
 * Indices follow the game's Overlay enum (dw/utils.h). SHOP_REL has no entry:
 * its code is linked into the main executable. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "dw1_native.h"

#define OVL_DECL(name) extern unsigned char dw1_ovl_##name##_start[], dw1_ovl_##name##_end[];
OVL_DECL(btl)
OVL_DECL(std)
OVL_DECL(fish)
OVL_DECL(evl)
OVL_DECL(kar)
OVL_DECL(vs)
OVL_DECL(mov)
OVL_DECL(doo2)
OVL_DECL(dooa)
OVL_DECL(trn)
OVL_DECL(dget)
OVL_DECL(trn2)
OVL_DECL(murd)
OVL_DECL(endi)
OVL_DECL(eab)

typedef struct {
    const char *name;
    unsigned char *start;
    unsigned char *end;
    unsigned char *pristine;
} OverlayRange;

#define OVL(name) { #name, dw1_ovl_##name##_start, dw1_ovl_##name##_end, NULL }
#define OVL_NONE { NULL, NULL, NULL, NULL }

static OverlayRange overlays[17] = {
    OVL_NONE,  /* 0: NONE */
    OVL(btl),  /* 1: BTL_REL */
    OVL(std),  /* 2: STD_REL */
    OVL(fish), /* 3: FISH_REL */
    OVL(evl),  /* 4: EVL_REL */
    OVL(kar),  /* 5: KAR_REL */
    OVL(vs),   /* 6: VS_REL */
    OVL(mov),  /* 7: MOV_REL */
    OVL(doo2), /* 8: DOO2_REL */
    OVL(dooa), /* 9: DOOA_REL */
    OVL(trn),  /* 10: TRN_REL */
    OVL_NONE,  /* 11: SHOP_REL (resident) */
    OVL(dget), /* 12: DGET_REL */
    OVL(trn2), /* 13: TRN2_REL */
    OVL(murd), /* 14: MURD_REL */
    OVL(endi), /* 15: ENDI_REL */
    OVL(eab),  /* 16: EAB_REL */
};

void dw1_overlay_init(void)
{
    size_t i;

    for (i = 0; i < sizeof(overlays) / sizeof(overlays[0]); i++) {
        OverlayRange *o = &overlays[i];
        size_t size;

        if (o->name == NULL)
            continue;
        size = (size_t)(o->end - o->start);
        o->pristine = malloc(size ? size : 1);
        if (o->pristine == NULL) {
            fprintf(stderr, "dw1: out of memory for overlay %s\n", o->name);
            abort();
        }
        memcpy(o->pristine, o->start, size);
    }
}

void dw1_overlay_reset(int lib)
{
    OverlayRange *o;

    if (lib <= 0 || lib >= (int)(sizeof(overlays) / sizeof(overlays[0])))
        return;
    o = &overlays[lib];
    if (o->name == NULL || o->pristine == NULL)
        return;
    memcpy(o->start, o->pristine, (size_t)(o->end - o->start));
}

/* Retail load addresses of the overlays (REL_BIN_OFFSETS in utils2.c). The
 * native loader never reads code into them; they only have to exist. */
char btl_START[1], std_START[1], fish_START[1], evl_START[1], kar_START[1], vs_START[1],
    mov_START[1], doo2_START[1], dooa_START[1], trn_START[1], dget_START[1], trn2_START[1],
    murd_START[1], endi_START[1], eab_START[1];
